-- Улирлын спонсорууд (ерөнхий спонсор / спонсор / хамтрагч)
-- Supabase SQL Editor дээр нэг удаа ажиллуулна. Давтан ажиллуулахад аюулгүй.
CREATE TABLE IF NOT EXISTS public."season_sponsors" (
  "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "season_id" int NOT NULL,
  "name" varchar(120) NOT NULL,
  "logo" varchar(255) DEFAULT NULL,
  "url" varchar(255) DEFAULT NULL,
  "tier" text NOT NULL DEFAULT 'sponsor' CHECK ("tier" IN ('title','sponsor','partner')),
  "sort_order" smallint NOT NULL DEFAULT 0,
  "created_at" timestamp without time zone DEFAULT public.app_now()
);
CREATE INDEX IF NOT EXISTS "season_sponsors_season_id" ON public."season_sponsors" ("season_id");
ALTER TABLE public."season_sponsors" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public."season_sponsors" FROM anon, authenticated;
